import os
import time
import yfinance as yf
from flask import Flask, jsonify
import threading
from datetime import datetime

app = Flask(__name__)

SYMBOLS_ENV = os.getenv("SYMBOLS", "TSLA,ETH-USD,NVDA,BTC-USD,AAPL,MSFT,SPY,EURUSD=X")
SYMBOLS = [s.strip() for s in SYMBOLS_ENV.split(",") if s.strip()]

RSI_BUY = 40
RSI_SELL = 60
FETCH_INTERVAL = 120
STOP_LOSS_PCT = 0.02
TAKE_PROFIT_PCT = 0.03
MAX_POSITION_PCT = 0.10

state = {
    "trades": 60,
    "equity": 89719.42,
    "cash": 82258.36,
    "pnl_hoy": -146.81,
    "auto_on": True,
    "version": "V5.5.5 PRO",
    "symbols": SYMBOLS,
    "rsi_buy": RSI_BUY,
    "rsi_sell": RSI_SELL,
    "stop_loss": "2%",
    "take_profit": "3%",
    "last_update": datetime.now().strftime("%H:%M:%S")
}

open_positions = {"ETH-USD": {"entry": 2488.71, "qty": 3}}

def calculate_rsi(symbol):
    try:
        ticker = yf.Ticker(symbol)
        hist = ticker.history(period="14d")
        if len(hist) < 14: return 50
        delta = hist['Close'].diff()
        gain = (delta.where(delta > 0, 0)).rolling(window=14).mean()
        loss = (-delta.where(delta < 0, 0)).rolling(window=14).mean()
        rs = gain / loss
        rsi = 100 - (100 / (1 + rs))
        return round(rsi.iloc[-1], 2)
    except Exception as e:
        if "429" in str(e): time.sleep(FETCH_INTERVAL)
        return 50

def trading_loop():
    while True:
        try:
            for symbol in SYMBOLS:
                ticker = yf.Ticker(symbol)
                hist = ticker.history(period="14d")
                if len(hist) < 14: 
                    time.sleep(5)
                    continue
                current_price = float(hist['Close'].iloc[-1])
                rsi = calculate_rsi(symbol)
                if symbol in open_positions:
                    entry = open_positions[symbol]["entry"]
                    qty = open_positions[symbol]["qty"]
                    pnl_pct = (current_price - entry) / entry
                    pnl_usd = (current_price - entry) * qty
                    if pnl_pct >= TAKE_PROFIT_PCT or pnl_pct <= -STOP_LOSS_PCT or rsi > RSI_SELL:
                        state["cash"] += current_price * qty
                        state["pnl_hoy"] += pnl_usd
                        del open_positions[symbol]
                        state["trades"] += 1
                elif rsi < RSI_BUY and symbol not in open_positions:
                    max_cash = state["cash"] * MAX_POSITION_PCT
                    if state["cash"] > max_cash and max_cash > current_price:
                        qty = int(max_cash / current_price)
                        if qty > 0:
                            open_positions[symbol] = {"entry": current_price, "qty": qty}
                            state["cash"] -= qty * current_price
                            state["trades"] += 1
                time.sleep(5)
            equity_pos = 0
            for s, p in open_positions.items():
                try:
                    price = float(yf.Ticker(s).history(period="1d")['Close'].iloc[-1])
                    equity_pos += p["qty"] * price
                except:
                    equity_pos += p["qty"] * p["entry"]
            state["equity"] = round(state["cash"] + equity_pos, 2)
            state["last_update"] = datetime.now().strftime("%H:%M:%S COL")
            time.sleep(FETCH_INTERVAL)
        except Exception as e:
            print(f"[ERROR] {e}")
            time.sleep(60)

